31: const SAVE_KEY='starfall-command-save-v1';const freshSave=()=>({credits:180,shards:0,profiles:heroDefs.map(()=>({level:1,xp:0,gear:[0,0,0]})),wins:0});let save;try{const raw=JSON.parse(localStorage.getItem(SAVE_KEY)||'null');save=raw&&Array.isArray(raw.profiles)?raw:freshSave()}catch(e){save=freshSave()}save.profiles=heroDefs.map((_,i)=>{const p=save.profiles[i]||{};return{level:Math.max(1,p.level||1),xp:Math.max(0,p.xp||0),gear:[0,1,2].map(n=>Math.max(0,(p.gear||[])[n]||0))}});save.credits=Math.max(0,save.credits||0);save.shards=Math.max(0,save.shards||0);save.wins=save.wins||0;function saveGame(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(save))}catch(e){}}function profile(kind){return save.profiles[kind]}function gearPower(kind){return profile(kind).gear.reduce((a,b)=>a+b,0)}function heroPower(kind){return 1+(profile(kind).level-1)*.12+gearPower(kind)*.06}function maxHeroHp(kind){return Math.round(heroDefs[kind].hp*(1+(profile(kind).level-1)*.07+profile(kind).gear[1]*.08))}let selected=[0,1,2],roster=[],hero,skillDefs=[],missionStage=1,difficulty='normal',upgradeHero=0;const keys={},skillsEl=$('skills');
